<?php
require_once __DIR__ . '/../../includes/auth.php';requireLogin();$db=getDB();$id=(int)($_GET['id']??0);
$st=$db->prepare("SELECT * FROM propostas WHERE id=? AND status='aprovada' AND ordem_servico_id IS NULL");$st->execute([$id]);$p=$st->fetch();if(!$p){$_SESSION['msg']='A proposta não está disponível para conversão.';header('Location:view.php?id='.$id);exit;}
$db->beginTransaction();try{$num='OS'.date('Ymd').str_pad((int)$db->query('SELECT COUNT(*)+1 FROM ordens_servico')->fetchColumn(),4,'0',STR_PAD_LEFT);$db->prepare("INSERT INTO ordens_servico(numero,cliente_id,usuario_responsavel_id,status,tipo,potencia_projeto,quantidade_paineis,area_instalacao,geracao_estimada_kwh,data_orcamento,valor_total,valor_materiais,valor_servicos,desconto,forma_pagamento,observacoes) VALUES(?,?,?,'aprovado','instalacao',?,?,?,?,?,?,?,?,?,?,?)")->execute([$num,$p['cliente_id'],$p['usuario_id'],$p['potencia_kwp'],$p['quantidade_modulos'],$p['area_necessaria_m2'],$p['geracao_mensal_kwh'],$p['data_proposta'],$p['valor_total'],$p['valor_equipamentos'],$p['valor_servicos'],$p['desconto'],$p['condicoes_pagamento'],'Gerada a partir da proposta '.$p['numero']]);$osid=(int)$db->lastInsertId();$ins=$db->prepare("INSERT INTO contas(ordem_servico_id,cliente_id,tipo,descricao,valor,data_vencimento,status,observacoes) VALUES(?,?,'receber',?,?,?,'pendente',?)");if((float)$p['entrada']>0)$ins->execute([$osid,$p['cliente_id'],'Entrada da proposta '.$p['numero'],$p['entrada'],$p['data_proposta'],'Gerada automaticamente na conversão da proposta']);if((float)$p['saldo']>0)$ins->execute([$osid,$p['cliente_id'],'Saldo da proposta '.$p['numero'],$p['saldo'],$p['validade']?:date('Y-m-d',strtotime('+30 days')),'Condição: '.$p['condicoes_pagamento']]);$db->prepare("UPDATE propostas SET status='convertida',ordem_servico_id=? WHERE id=?")->execute([$osid,$id]);$db->commit();$_SESSION['msg']='Proposta convertida na OS '.$num.' e contas a receber geradas!';header('Location:../os/view.php?id='.$osid);exit;}catch(Throwable $e){$db->rollBack();$_SESSION['msg']='Erro ao converter a proposta.';header('Location:view.php?id='.$id);exit;}
